/* eslint-disable */
import React, { useRef, useState } from "react";
import { Link } from "react-router-dom";

import IndexNavbar from "components/Navbars/IndexNavbar.js";
import Footer from "components/Footers/Footer.js";
import HeroImage from "assets/img/bg1.png";
import BannerImage from "assets/img/banniere.png";

import NewsStack from "components/newsStack";
import PrettyCalendar from "components/calendar";
import ressourcesImg from "assets/img/ressourcesImg.png"; // mets ici ta photo
import IconDoc from "assets/img/doclogo.png";

import News1 from "assets/img/mbaye.png";
import News2 from "assets/img/newdeal.jpg";
import News3 from "assets/img/sim.jpg";

export default function Index() {
  const [bannerOffset, setBannerOffset] = useState(0);
  const twoColRef = useRef(null);

  return (
    <>
      <IndexNavbar fixed />

      {/* HERO */}
      <section
        className="relative mt-16 md:mt-20 h-screen max-h-860-px flex items-center"
        style={{
          backgroundImage: `linear-gradient(rgba(107, 20, 15, 0.65), rgba(107, 20, 15, 0.25)), url(${HeroImage})`,
          backgroundSize: "cover",
          backgroundPosition: "center 30%",
          backgroundRepeat: "no-repeat",
        }}
      >
        <div className="container mx-auto relative z-10 flex flex-wrap items-center">
          <div className="w-full lg:w-6/12 px-4">
            <h1 className="font-bold text-5xl md:text-7xl text-white leading-tight">
              Dalal ak jàamm,
            </h1>
            <p className="mt-6 text-2xl md:text-3xl font-light text-white max-w-xl">
              Nassour !
            </p>
          </div>
        </div>
      </section>

      {/* 2 colonnes : Calendrier + Actualités */}
      <section className="relative bg-white py-16">
        <div className="container mx-auto px-4">
          <div ref={twoColRef} className="flex flex-row items-start space-x-8">
            <div className="w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Un jour spécial pour ?</h3>
              <PrettyCalendar
                initialYear={2023}
                initialMonth={2}
                selectedDay={20}
                events={[
                  { date: "2023-02-20", label: "Anniversaire de Ousmane DIA" },
                  { date: "2023-02-16", label: "Réunion Produits" },
                ]}
              />
            </div>

            <div className="w-1/2 min-w-0">
              <h3 className="text-[#1c2b68] font-semibold text-xl mb-3">Actualités</h3>
              <NewsStack
                items={[
                  { img: News2, href: "#" },
                  { img: News3, href: "#" },
                  { img: News1, href: "#" },
                ]}
              />
            </div>
          </div>
        </div>
      </section>

      {/* Bannière — chevauche légèrement les actus */}
      <section
        className="relative w-full z-20"
        style={{
          marginTop: "-500px", // ← ajuste ici la hauteur à "remonter"
        }}
      >
        <img
          src={BannerImage}
          alt="Bannière"
          className="w-full h-[500px] object-cover rounded-lg shadow-lg"
        />
      </section>
      {/* <section className="relative w-full bg-white py-16">
        <div className="w-full">
          <img
            src={ressourcesImg}
            alt="Nouvelle section"
            className="rounded-lg shadow-lg object-cover"
            style={{
              width: "40%",   // 2/5 largeur de la bannière
              height: "33%",  // 1/3 hauteur de la bannière
              marginLeft: "0", // bien collé à gauche
              marginTop: "-350px"
            }}
          />
        </div>
      </section> */}
      {/* === SECTION : Ressources + 2 cartes === */}
      <section className="relative w-full bg-white pt-10 pb-20">
        <div className="container mx-auto px-6 lg:px-12">
          <div className="grid grid-cols-12 gap-6 lg:gap-10 items-start">
            {/* Image à gauche (1/3 hauteur de la bannière ~170px, ~2/5 largeur) */}
            <div className="col-span-12 lg:col-span-5">
              <img
                src={ressourcesImg}
                alt="Ressources"
                className="w-full h-[170px] object-cover rounded-[12px] shadow-[0_8px_24px_rgba(0,0,0,0.12)]"
              />
            </div>

            {/* 2 cartes à droite */}
            <div className="col-span-12 lg:col-span-7">
              <div className="flex flex-col md:flex-row gap-6 lg:gap-8">
                {/* Carte 1 : Top Ressources */}
                <div className="bg-[#F1F1F1] rounded-[18px] shadow-[0_10px_28px_rgba(0,0,0,0.12)] border border-[#E9E9ED] w-full md:w-[340px] p-6">
                  <h4 className="text-[22px] font-semibold text-[#0b132b] mb-5">
                    Top Ressources
                  </h4>

                  <div className="flex items-start gap-4">
                    <img src={IconDoc} alt="" className="w-14 h-14 object-contain mt-1" />
                    <ul className="space-y-3 text-[#0b132b]">
                      <li><a className="underline hover:opacity-80" href="#">Omni365</a></li>
                      <li><a className="underline hover:opacity-80" href="#">Vision Accel</a></li>
                      <li><a className="underline hover:opacity-80" href="#">Karangue</a></li>
                    </ul>
                  </div>

                  <div className="mt-6 text-center text-[#2b2b2b]">Voir plus</div>
                </div>

                {/* Carte 2 : Vie d’entreprise */}
                <div className="bg-[#F1F1F1] rounded-[18px] shadow-[0_10px_28px_rgba(0,0,0,0.12)] border border-[#E9E9ED] w-full md:w-[340px] p-6">
                  <h4 className="text-[22px] font-semibold text-[#0b132b] mb-5">
                    Vie d’entreprise
                  </h4>

                  <div className="flex items-start gap-4">
                    <img src={IconPeople} alt="" className="w-14 h-14 object-contain mt-1" />
                    <ul className="space-y-3 text-[#0b132b]">
                      <li><a className="underline hover:opacity-80" href="#">Qui fait quoi ?</a></li>
                      <li><a className="underline hover:opacity-80" href="#">Initiative QVT</a></li>
                      <li><a className="underline hover:opacity-80" href="#">Temps forts RH</a></li>
                    </ul>
                  </div>

                  <div className="mt-6 text-center text-[#2b2b2b]">Voir plus</div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* SECTION suivante */}
      <section id="features" className="py-24 bg-blueGray-50">
        <div className="container mx-auto px-4 text-center max-w-3xl">
          <h2 className="text-3xl md:text-4xl font-semibold text-blueGray-800">Ce que vous obtenez</h2>
        </div>
      </section>

      <Footer />
    </>
  );
}
